using System.Diagnostics;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Text.Json;
using TutorFlow.Evals;

namespace TutorFlow.Tests;

/// <summary>
/// Integridad del runner de evals (CA-14, CA-16): falla cerrado ante datos o casos mal formados.
/// Convenciones asumidas (a confirmar con el implementador):
///  - Corpus.Cargar lanza una excepcion (cualquier tipo) ante usuarios inconsistentes.
///  - El runner (Program) termina con codigo 2 ante un caso con campo desconocido, y el mensaje nombra el campo.
///  - Con LLM_API_KEY ausente el runner escribe un aviso que menciona LLM_API_KEY (stdout o stderr).
/// Sin red externa: el runner se ejecuta como proceso contra un servidor local falso o un puerto cerrado.
/// </summary>
public sealed class EvalsIntegridadTests : IDisposable
{
    const string Doc = "reglamento-x.md";
    readonly List<string> _dirs = new();

    public void Dispose()
    {
        foreach (var d in _dirs) { try { Directory.Delete(d, true); } catch { } }
    }

    string NuevoDir()
    {
        var d = Path.Combine(Path.GetTempPath(), "tf-integ-" + Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(d);
        _dirs.Add(d);
        return d;
    }

    string Datos(params (string archivo, string json)[] api)
    {
        var dir = NuevoDir();
        Directory.CreateDirectory(Path.Combine(dir, "reglamento"));
        Directory.CreateDirectory(Path.Combine(dir, "api"));
        File.WriteAllText(Path.Combine(dir, "reglamento", Doc), "# T\n\n## Plazos\n\ntexto\n");
        foreach (var (a, j) in api) File.WriteAllText(Path.Combine(dir, "api", a), j);
        return dir;
    }

    const string Estudiantes = """
        [ { "id": "S-1", "nombre": "Ana Uno Pérez", "programa": "Alfa", "semestre": 2 },
          { "id": "S-2", "nombre": "Beto Dos Gómez", "programa": "Alfa", "semestre": 3 } ]
        """;
    const string Coordinadores = """
        [ { "id": "K-1", "nombre": "Laura Coord", "programa": "Alfa" } ]
        """;

    // ---- (1) Corpus.Cargar falla cerrado ----

    [Fact]
    public void Integridad_corpus_valido_de_control_carga()
    {
        var c = Corpus.Cargar(Datos(("estudiantes.json", Estudiantes), ("coordinadores.json", Coordinadores)));
        Assert.Equal(2, c.Estudiantes.Count);
        Assert.Single(c.Coordinadores);
    }

    [Fact]
    public void Integridad_corpus_archivo_con_formas_mezcladas_con_y_sin_semestre_es_error()
    {
        const string mezclado = """
            [ { "id": "S-1", "nombre": "Ana Uno Pérez", "programa": "Alfa", "semestre": 2 },
              { "id": "S-2", "nombre": "Beto Dos Gómez", "programa": "Alfa" } ]
            """;
        var dir = Datos(("usuarios.json", mezclado));
        Assert.ThrowsAny<Exception>(() => Corpus.Cargar(dir));
    }

    [Fact]
    public void Integridad_corpus_mismo_id_en_dos_roles_es_error()
    {
        const string coordConIdDeEstudiante = """
            [ { "id": "S-1", "nombre": "Laura Coord", "programa": "Alfa" } ]
            """;
        var dir = Datos(("estudiantes.json", Estudiantes), ("coordinadores.json", coordConIdDeEstudiante));
        Assert.ThrowsAny<Exception>(() => Corpus.Cargar(dir));
    }

    [Fact]
    public void Integridad_corpus_sin_ningun_estudiante_es_error()
    {
        var dir = Datos(("coordinadores.json", Coordinadores));
        Assert.ThrowsAny<Exception>(() => Corpus.Cargar(dir));
    }

    [Fact]
    public void Integridad_corpus_sin_ningun_coordinador_es_error()
    {
        var dir = Datos(("estudiantes.json", Estudiantes));
        Assert.ThrowsAny<Exception>(() => Corpus.Cargar(dir));
    }

    [Fact]
    public void Integridad_corpus_sin_usuarios_es_error()
    {
        var dir = Datos();
        Assert.ThrowsAny<Exception>(() => Corpus.Cargar(dir));
    }

    [Fact]
    public void Integridad_corpus_real_de_data_carga_con_ambos_roles()
    {
        var raiz = SubirA("TutorFlow.sln");
        var c = Corpus.Cargar(Path.Combine(raiz, "data"));
        Assert.NotEmpty(c.Estudiantes);
        Assert.NotEmpty(c.Coordinadores);
        Assert.NotEmpty(c.Citas);
    }

    // ---- (2) Respuesta vacia en un 200 falla ----

    static string Cuerpo(string respuesta) => JsonSerializer.Serialize(new
    {
        respuesta,
        citas = Array.Empty<object>(),
        usoDatosEstudiante = false,
        tokens = 1,
        costoUsd = 0.0,
    });

    Corpus CorpusBase() => Corpus.Cargar(Datos(("estudiantes.json", Estudiantes), ("coordinadores.json", Coordinadores)));

    static Caso Laxo(Action<Caso>? cfg = null)
    {
        var c = new Caso { Id = "L", Escenario = "ESC-X", Usuario = new("estudiante", "S-1"), Pregunta = "p", CodigoEsperado = 200 };
        cfg?.Invoke(c);
        return c;
    }

    [Theory]
    [InlineData("")]
    [InlineData("   ")]
    [InlineData("\n\t  \r\n")]
    public void Integridad_200_con_respuesta_vacia_o_en_blanco_falla_en_caso_laxo(string respuesta)
using System.Text;
using System.Text.Json;
using TutorFlow.Evals;

// Raíz del repositorio y carpeta de datos, localizadas subiendo desde el directorio de trabajo.
static string? Subir(Func<string, bool> ok)
{
    for (var d = new DirectoryInfo(Directory.GetCurrentDirectory()); d != null; d = d.Parent)
        if (ok(d.FullName)) return d.FullName;
    return null;
}

var dataDir = Environment.GetEnvironmentVariable("EVALS_DATA");
var raiz = Subir(d => File.Exists(Path.Combine(d, "TutorFlow.sln")));
if (string.IsNullOrEmpty(dataDir))
{
    var padre = Subir(d => Directory.Exists(Path.Combine(d, "data", "reglamento")));
    dataDir = padre is null ? null : Path.Combine(padre, "data");
}
if (dataDir is null || !Directory.Exists(dataDir))
{
    Console.Error.WriteLine("No se encontró la carpeta de datos (use EVALS_DATA).");
    return 2;
}
var evalsDir = raiz is null ? Path.Combine(Directory.GetCurrentDirectory(), "evals") : Path.Combine(raiz, "evals");

var url = (Environment.GetEnvironmentVariable("EVALS_API_URL") is { Length: > 0 } u ? u : "http://localhost:8080").TrimEnd('/');
var pausaMs = int.TryParse(Environment.GetEnvironmentVariable("EVALS_PAUSA_MS"), out var pm) ? pm : 1500;
var esperaMs = int.TryParse(Environment.GetEnvironmentVariable("EVALS_ESPERA_MS"), out var em) ? em : 2000;
const int Reintentos = 3;
var llave = Environment.GetEnvironmentVariable("LLM_API_KEY"); // solo para R2; no se envía a ningún lado

if (string.IsNullOrEmpty(llave))
    Console.WriteLine("ADVERTENCIA: LLM_API_KEY no está definida en el entorno del runner; la regla de no filtrar la llave no se puede comprobar.");

var casos = new List<Caso>();
void CargarCasos(string ruta)
{
    var lista = JsonSerializer.Deserialize<List<Caso>>(File.ReadAllText(ruta), Evaluador.JsonOpts);
    if (lista != null) casos.AddRange(lista);
}
Corpus corpus;
try
{
    CargarCasos(Path.Combine(dataDir, "preguntas-ejemplo.json"));
    var extra = Path.Combine(evalsDir, "casos-adicionales.json");
    if (File.Exists(extra)) CargarCasos(extra);
    corpus = Corpus.Cargar(dataDir);
}
catch (Exception ex) when (ex is JsonException or InvalidDataException or IOException)
{
    Console.Error.WriteLine("Entrada de evals inválida: " + ex.Message);
    return 2;
}
using var http = new HttpClient { Timeout = TimeSpan.FromSeconds(120) };
var resultados = new List<ResultadoCaso>();

Console.WriteLine($"Evals contra {url}: {casos.Count} casos");
for (var i = 0; i < casos.Count; i++)
{
    var caso = casos[i];
    if (i > 0 && pausaMs > 0) await Task.Delay(pausaMs);
    var cuerpoPeticion = JsonSerializer.Serialize(new
    {
        pregunta = caso.Pregunta,
        usuario = new { rol = caso.Usuario.Rol, id = caso.Usuario.Id },
    });
    RespuestaHttp? resp = null;
    var motivoFinal = "";
    for (var intento = 0; intento <= Reintentos; intento++)
    {
        if (intento > 0) await Task.Delay(esperaMs * (1 << (intento - 1)));
        try
        {
            using var content = new StringContent(cuerpoPeticion, Encoding.UTF8, "application/json");
            using var hr = await http.PostAsync(url + "/api/asistente/preguntar", content);
            var texto = await hr.Content.ReadAsStringAsync();
            var codigo = (int)hr.StatusCode;
            if (codigo is 503 or 429) { motivoFinal = $"proveedor sin respuesta ({codigo})"; continue; }
            resp = new RespuestaHttp(codigo, texto);
            break;
        }
        catch (Exception ex) when (ex is HttpRequestException or TaskCanceledException)
        {
            motivoFinal = "error de red: " + ex.GetType().Name;
        }
    }
    var res = resp is null ? Evaluador.SinResultado(caso, motivoFinal) : Evaluador.Evaluar(caso, resp, corpus, llave);
    resultados.Add(res);
    var estado = res.Estado switch { Estado.Ok => "OK", Estado.Falla => "FALLA", _ => "SIN RESULTADO" };
    Console.WriteLine($"{res.Id,-8} {res.Escenario,-10} {estado,-13} {string.Join("; ", res.Motivos)}");
}

var resumen = Evaluador.Resumir(resultados);
var veredicto = resumen.CodigoSalida switch { 0 => "APROBADA", 1 => "REPROBADA", _ => "INCONCLUSA" };
Console.WriteLine();
Console.WriteLine($"Aprobadas: {resumen.Aprobadas}/{resumen.ConResultado} con resultado ({resumen.Total} casos, {resumen.SinResultado} sin resultado)");
Console.WriteLine($"Puntaje: {resumen.Puntaje:P1} (umbral {resumen.Umbral:P0})");
Console.WriteLine($"Reglas duras (R1 citas, R2 privacidad/llave): {(resumen.ReglasDurasOk ? "OK" : "VIOLADAS")}");
Console.WriteLine($"Tokens: total {resumen.TokensTotales}, promedio {resumen.TokensPromedio:F1} por pregunta");
Console.WriteLine($"Costo USD: total {resumen.CostoTotalUsd:F6}, promedio {resumen.CostoPromedioUsd:F6}, estimado por 1.000 preguntas {resumen.CostoPor1000Usd:F4}");
Console.WriteLine($"Veredicto: {veredicto}");

Directory.CreateDirectory(Path.Combine(evalsDir, "resultados"));
File.WriteAllText(Path.Combine(evalsDir, "resultados", "ultimo.json"),
    JsonSerializer.Serialize(new { fecha = DateTime.UtcNow, veredicto, resumen, casos = resultados },
        new JsonSerializerOptions { WriteIndented = true, PropertyNamingPolicy = JsonNamingPolicy.CamelCase }));
return resumen.CodigoSalida;

