                    ["type"] = "tool_use", ["id"] = l.Id, ["name"] = l.Nombre, ["input"] = JsonNode.Parse(l.Args),
                }).ToArray()),
                ["usage"] = UsoAnthropic(entrada, salida, cacheCrea, cacheLee),
            }.ToJsonString();

